{
  "rules": [
    {
      "category": "screening_restriction",
      "title": "Fair Chance in Housing Act Criminal History Screening Limits",
      "requirement": "Landlords cannot inquire into an applicant's criminal history before making a conditional offer, except for specific lifetime sex offender registration or methamphetamine manufacturing convictions. Even after a conditional offer, only certain serious or recent convictions may be considered, and the landlord must perform an individualized assessment and provide specific written disclosures before withdrawing an offer.",
      "requirement_es": "Los propietarios no pueden consultar el historial penal de un solicitante antes de hacer una oferta condicional, salvo en casos específicos de registro de por vida para delincuentes sexuales o condenas por fabricación de metanfetamina. Incluso después de una oferta condicional, solo se pueden considerar ciertas condenas graves o recientes, y el arrendador debe realizar una evaluación individualizada y proporcionar notificaciones específicas por escrito antes de retirar una oferta.",
      "key_value": null,
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Dwelling units in owner-occupied premises of not more than four dwelling units",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true,
                "note": "other than a dwelling unit in an owner-occupied premises of not more than four dwelling units"
              },
              {
                "field": "units",
                "operator": "<=",
                "value": 4,
                "note": "not more than four dwelling units"
              }
            ]
          }
        }
      ],
      "effective_date": "2022-01-01",
      "superseded_date": null,
      "status": "enacted",
      "precedence": {
        "relationship": "stacks_with",
        "target_scope": "none",
        "source_language": null
      },
      "penalty": "Civil penalties up to $1,000 for a first violation within 5 years, up to $5,000 for a second violation within 5 years, and up to $10,000 for two or more prior violations within 7 years; potential order to offer housing, return application fees, and pay up to $1,000 to the applicant.",
      "source_citation": "N.J.S.A. 46:8-55, 46:8-56",
      "quote": {
        "chunk": "c8",
        "start_words": "A housing provider shall not require an applicant",
        "end_words": "prior to making a conditional offer."
      },
      "confidence": 0.95
    },
